input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone WHERE {
  ?zone rdf:type brick:Zone .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?p ?class WHERE {
  ?p rdf:type ?class .
  FILTER(str(?class) ENDs "AirTemperatureSensor" || str(?class) ENDS "AirTemperature")
}

SELECT ?p ?class ?ref WHERE {
  ?p a ?class ; ref:hasExternalReference ?ref .
  FILTER(str(?p) CONTAINS "Perimeter_ZN_2")
}

